// Notchset combobox 2.1.0 · https://notchset.dev/changelog
"use client";
import * as React from "react";
import { Combobox as Base } from "@base-ui/react/combobox";
import { Check, ChevronDown, Plus } from "lucide-react";
import { cn } from "@/lib/utils";
import { fieldSurface } from "@/components/ui/notchset/field";
import { popupEmpty, popupItem, popupPositioner, popupSurface } from "@/lib/notchset/popup";
import { usePortalContainer } from "@/lib/notchset/portal";

/*
 * Combobox: pick one of a long list by typing (a company, an owner). The first match is highlighted, so
 * type-then-Enter picks it. Shows what is chosen when closed; says "No matches" rather than an empty box. With
 * `onCreate`, a name that matches nothing exactly is offered as the last item ("Create “Loom”"): the host makes
 * the record and returns its value, which is then chosen, so typing a new name never dead-ends.
 */
type ComboboxOption = { value: string; label: string; icon?: React.ReactNode; hint?: React.ReactNode };
type ComboboxProps = {
  options: ComboboxOption[];
  value: string | null;
  onValueChange: (value: string | null) => void;
  placeholder?: string | undefined;
  "aria-label"?: string | undefined;
  disabled?: boolean | undefined;
  /** Makes a record from the typed name and returns its value (null when refused); offered when nothing matches exactly. */
  onCreate?: ((name: string) => string | null | undefined) | undefined;
  className?: string | undefined;
};
const CREATE = "\u0000create";

function Combobox({ options, value, onValueChange, placeholder = "Search…", disabled, onCreate, className, ...aria }: ComboboxProps) {
  const portalContainer = usePortalContainer();
  const [typed, setTyped] = React.useState("");
  const chosen = options.find((o) => o.value === value) ?? null;
  const name = typed.trim();
  const offer = !!onCreate && !!name && !options.some((o) => o.label.toLowerCase() === name.toLowerCase());
  return (
    <Base.Root
      items={offer ? [...options, { value: CREATE, label: name }] : options}
      value={chosen}
      onInputValueChange={(v) => setTyped(v)}
      onValueChange={(o) => {
        const x = o as ComboboxOption | null;
        if (x?.value === CREATE) {
          const made = onCreate!(x.label);
          if (made) onValueChange(made);
          return;
        }
        onValueChange(x?.value ?? null);
      }}
      itemToStringLabel={(o: ComboboxOption) => o.label}
      isItemEqualToValue={(a: ComboboxOption, b: ComboboxOption) => a.value === b.value}
      autoHighlight
      disabled={disabled}
    >
      <Base.InputGroup data-slot="combobox" className={cn(fieldSurface, "flex h-[var(--ns-field)] items-center gap-2 pr-1.5", className)}>
        {chosen?.icon && <span className="flex shrink-0 [&_svg:not([data-slot=company-mark])]:size-3.5">{chosen.icon}</span>}
        <Base.Input placeholder={placeholder} {...aria} className="h-full min-w-0 flex-1 bg-transparent outline-hidden placeholder:text-[var(--ns-ink-3)]" />
        <Base.Trigger aria-label="Show options" className="group grid size-6 cursor-pointer place-items-center rounded-[5px] text-[var(--ns-ink-3)] outline-hidden hover:text-[var(--ns-ink)]">
          <ChevronDown className="size-3.5 [transition:rotate_160ms_var(--ns-ease)] group-data-popup-open:rotate-180" />
        </Base.Trigger>
      </Base.InputGroup>
      <Base.Portal container={portalContainer}>
        <Base.Positioner sideOffset={4} collisionPadding={8} className={popupPositioner}>
          <Base.Popup data-slot="combobox-popup" data-ns-moves="" className={popupSurface}>
            <Base.Empty className={popupEmpty}>No matches</Base.Empty>
            <Base.List>
              {(o: ComboboxOption) => (
                <Base.Item key={o.value} value={o} className={popupItem}>
                  {o.value === CREATE ? <Plus aria-hidden /> : o.icon}
                  <span className="min-w-0 flex-1 truncate">{o.value === CREATE ? `Create “${o.label}”` : o.label}</span>
                  {o.hint && <span className="text-[length:var(--ns-text-meta)] text-[var(--ns-ink-3)]">{o.hint}</span>}
                  <Base.ItemIndicator className="ml-2">
                    <Check />
                  </Base.ItemIndicator>
                </Base.Item>
              )}
            </Base.List>
          </Base.Popup>
        </Base.Positioner>
      </Base.Portal>
    </Base.Root>
  );
}

export { Combobox, type ComboboxOption, type ComboboxProps };

// Notchset combobox 2.1.0 · https://notchset.dev/changelog
/*
 * The one popup surface every list that opens from a control uses (select, combobox, recipient picker, and
 * menus in batch 3): the prototype's .menu. It drops just below its control, and on a phone it becomes a
 * bottom sheet with a grab handle and finger-sized rows. Kept as class strings so each primitive's own parts
 * wear the same look.
 */

/** On the Positioner: above everything but dialogs; on a phone, pinned to the bottom edge as a sheet (above a tab bar
    when the app sets --ns-sheet-bottom to its height). */
export const popupPositioner =
  "z-50 outline-hidden max-[600px]:!fixed max-[600px]:!inset-x-2 max-[600px]:!top-auto max-[600px]:!bottom-[calc(var(--ns-sheet-bottom)+env(safe-area-inset-bottom,0px))] max-[600px]:!left-2 max-[600px]:!w-auto max-[600px]:!transform-none";

/** On the Popup. */
export const popupSurface =
  "min-w-[max(var(--anchor-width,0px),180px)] max-h-[min(420px,70vh,var(--available-height,70vh))] overflow-auto overscroll-contain rounded-[var(--ns-radius-lg)] bg-[var(--ns-raised)] p-[5px] text-[length:var(--ns-text-body)] text-[var(--ns-ink)] shadow-[0_0_0_1px_var(--ns-line),var(--ns-shadow-float)] outline-hidden origin-[var(--transform-origin)] " +
  "[animation:ns-menu-in_var(--ns-time-menu)_var(--ns-ease)] data-ending-style:opacity-0 data-ending-style:[transition:opacity_110ms_ease] " +
  "max-[600px]:w-auto max-[600px]:min-w-0 max-[600px]:max-h-[70dvh] max-[600px]:rounded-[var(--ns-radius-xl)] max-[600px]:px-1.5 max-[600px]:pt-3.5 max-[600px]:pb-1.5 max-[600px]:[animation:ns-sheet-up_var(--ns-time-panel)_var(--ns-ease-panel)] " +
  "max-[600px]:before:absolute max-[600px]:before:top-[5px] max-[600px]:before:left-1/2 max-[600px]:before:h-1 max-[600px]:before:w-9 max-[600px]:before:-translate-x-1/2 max-[600px]:before:rounded-full max-[600px]:before:bg-[var(--ns-line)] max-[600px]:before:content-['']";

/** On each item. Highlight (pointer or arrow keys) is the hover wash; the chosen item carries a check. */
export const popupItem =
  "flex w-full min-h-[var(--ns-menu-row)] cursor-default items-center gap-[9px] rounded-[7px] px-[9px] text-left outline-hidden select-none data-highlighted:bg-[var(--ns-hover)] data-disabled:opacity-45 [&_svg:not([data-slot=company-mark])]:size-3.5 [&_svg]:shrink-0";

/** The quiet line a list shows when nothing matches. */
export const popupEmpty = "px-[9px] py-2 text-[length:var(--ns-text-small)] text-[var(--ns-ink-3)] empty:hidden";

// Notchset combobox 2.1.0 · https://notchset.dev/changelog
import * as React from "react";

/*
 * Where overlays (dialogs, menus, popovers, tooltips, toasts, sheets) portal to. By default the document body; a
 * host that themes or scopes a region (a preview stage, a shadow root, a tile in another theme) wraps it in
 * PortalContainer with an element inside that scope, so its overlays keep the region's roles and light or dark.
 */
const PortalContainerContext = React.createContext<HTMLElement | null>(null);

const PortalContainer = PortalContainerContext.Provider;

/** The element overlays portal into here, or undefined for the document body. */
function usePortalContainer(): HTMLElement | undefined {
  return React.useContext(PortalContainerContext) ?? undefined;
}

export { PortalContainer, PortalContainerContext, usePortalContainer };
